'use client'

import type { ColumnDef } from '@tanstack/react-table'
import { ChevronRight } from 'lucide-react'

export type Order = {
  id: string
  customer: string
  category: string
  amount: number
  status: string
}

const currency = (value: number) =>
  value.toLocaleString('en-US', { style: 'currency', currency: 'USD' })

export const columns: ColumnDef<Order>[] = [
  {
    accessorKey: 'category',
    header: 'Category',
    cell: ({ row, cell, getValue }) => {
      if (cell.getIsGrouped()) {
        return (
          <button
            type="button"
            onClick={row.getToggleExpandedHandler()}
            className="flex items-center gap-1.5 font-medium"
          >
            <ChevronRight
              className={`h-3.5 w-3.5 transition-transform ${
                row.getIsExpanded() ? 'rotate-90' : ''
              }`}
            />
            {getValue() as string}
            <span className="font-normal text-muted-foreground">
              ({row.subRows.length})
            </span>
          </button>
        )
      }
      if (cell.getIsPlaceholder()) return null
      return <span className="pl-5">{getValue() as string}</span>
    },
  },
  {
    accessorKey: 'customer',
    header: 'Customer',
    cell: ({ cell, getValue }) =>
      cell.getIsAggregated() ? null : (getValue() as string),
  },
  {
    accessorKey: 'status',
    header: 'Status',
    cell: ({ cell, getValue }) =>
      cell.getIsAggregated() ? null : (getValue() as string),
  },
  {
    accessorKey: 'amount',
    header: 'Amount',
    aggregationFn: 'sum',
    cell: ({ cell, getValue }) => (
      <span className={cell.getIsAggregated() ? 'font-medium' : undefined}>
        {currency(getValue() as number)}
      </span>
    ),
  },
]

'use client'

import {
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  getGroupedRowModel,
  useReactTable,
} from '@tanstack/react-table'

import type {
  ColumnDef,
  ExpandedState,
  GroupingState,
} from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { useState } from 'react'
import { cn } from '#/lib/utils.ts'

interface GroupedDataTableProps<TData> {
  columns: ColumnDef<TData, any>[]
  data: TData[]
  groupBy: string
}

export function GroupedDataTable<TData>({
  columns,
  data,
  groupBy,
}: GroupedDataTableProps<TData>) {
  const [grouping, setGrouping] = useState<GroupingState>([groupBy])
  const [expanded, setExpanded] = useState<ExpandedState>(true)

  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getGroupedRowModel: getGroupedRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
    onGroupingChange: setGrouping,
    onExpandedChange: setExpanded,
    state: {
      grouping,
      expanded,
    },
  })

  return (
    <div className="overflow-hidden rounded-md border">
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <TableHead key={header.id}>
                  {header.isPlaceholder
                    ? null
                    : flexRender(
                        header.column.columnDef.header,
                        header.getContext(),
                      )}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table.getRowModel().rows.length ? (
            table.getRowModel().rows.map((row) => (
              <TableRow
                key={row.id}
                className={cn(row.getIsGrouped() && 'bg-muted/50')}
              >
                {row.getVisibleCells().map((cell) => (
                  <TableCell key={cell.id}>
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </TableCell>
                ))}
              </TableRow>
            ))
          ) : (
            <TableRow>
              <TableCell colSpan={columns.length} className="h-24 text-center">
                No results.
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
    </div>
  )
}
